<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Snake</title>
<style>
  :root {
    --bg: #10131a;
    --panel: #1a1f2b;
    --accent: #46e0a0;
    --accent2: #2fa876;
    --food: #ff5a6e;
    --text: #e6ecf3;
    --muted: #8b96a8;
  }
  * { box-sizing: border-box; }
  html, body {
    margin: 0;
    height: 100%;
    background: var(--bg);
    color: var(--text);
    font-family: system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
  }
  body {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    min-height: 100vh;
    gap: 16px;
    padding: 20px;
  }
  h1 {
    margin: 0;
    font-weight: 700;
    letter-spacing: 2px;
    font-size: 26px;
    color: var(--accent);
  }
  #score {
    font-size: 20px;
    font-variant-numeric: tabular-nums;
    color: var(--text);
  }
  #score b { color: var(--accent); }
  .board-wrap {
    padding: 10px;
    background: var(--panel);
    border-radius: 12px;
    box-shadow: 0 10px 40px rgba(0,0,0,0.5);
  }
  #snake {
    display: block;
    background: #0b0e14;
    border-radius: 6px;
    width: 440px;
    height: 440px;
  }
  .controls {
    display: flex;
    gap: 10px;
  }
  button {
    background: var(--panel);
    color: var(--text);
    border: 1px solid #2b3242;
    padding: 10px 20px;
    border-radius: 8px;
    font-size: 15px;
    cursor: pointer;
    transition: all .15s;
  }
  button:hover { border-color: var(--accent); color: var(--accent); }
  button:active { transform: translateY(1px); }
  #start { border-color: var(--accent2); }
  .status {
    height: 20px;
    color: var(--muted);
    font-size: 14px;
  }
  .status.dead { color: var(--food); font-weight: 600; }
</style>
</head>
<body>
  <h1>SNAKE</h1>
  <div id="score">Score: <b>0</b></div>
  <div class="board-wrap">
    <canvas id="snake" width="440" height="440"></canvas>
  </div>
  <div class="controls">
    <button id="start">Start</button>
    <button id="pause">Pause</button>
    <button id="reset">Reset</button>
  </div>
  <div class="status" id="status">Press Start or an arrow key</div>

<script>
(function () {
  const W = 20, H = 20;             // grid cells
  const canvas = document.getElementById('snake');
  const ctx = canvas.getContext('2d');
  const scoreEl = document.querySelector('#score b');
  const statusEl = document.getElementById('status');

  const CELL = canvas.width / W;   // pixels per cell

  let snakeArr, foodPos, dir, pendingDir, aliveFlag, scoreVal;
  let loopId = null;
  const SPEED = 110; // ms per tick

  function reset() {
    const cx = Math.floor(W / 2), cy = Math.floor(H / 2);
    // head first
    snakeArr = [
      [cx, cy],
      [cx - 1, cy],
      [cx - 2, cy]
    ];
    dir = 'right';
    pendingDir = 'right';
    aliveFlag = true;
    scoreVal = 0;
    placeFood();
    updateScore();
    setStatus('Ready');
    draw();
  }

  function updateScore() { scoreEl.textContent = scoreVal; }

  function setStatus(msg, dead) {
    statusEl.textContent = msg;
    statusEl.classList.toggle('dead', !!dead);
  }

  function occupied(x, y) {
    return snakeArr.some(s => s[0] === x && s[1] === y);
  }

  function placeFood() {
    const free = [];
    for (let x = 0; x < W; x++)
      for (let y = 0; y < H; y++)
        if (!occupied(x, y)) free.push([x, y]);
    if (free.length === 0) { foodPos = null; return; }
    foodPos = free[Math.floor(Math.random() * free.length)];
  }

  function setFood(x, y) {
    foodPos = [x | 0, y | 0];
    draw();
  }

  const OPP = { up: 'down', down: 'up', left: 'right', right: 'left' };
  const DELTA = {
    up: [0, -1], down: [0, 1], left: [-1, 0], right: [1, 0]
  };

  function setDir(d) {
    if (!DELTA[d]) return;
    // ignore 180 reversal relative to current heading
    if (OPP[d] === dir) return;
    pendingDir = d;
  }

  function tick() {
    if (!aliveFlag) return;
    dir = pendingDir;
    const [dx, dy] = DELTA[dir];
    const head = snakeArr[0];
    const nx = head[0] + dx;
    const ny = head[1] + dy;

    // wall collision
    if (nx < 0 || ny < 0 || nx >= W || ny >= H) {
      die();
      return;
    }

    const eating = foodPos && nx === foodPos[0] && ny === foodPos[1];

    // body collision: check against all cells except the tail that will move,
    // unless we're eating (tail stays).
    const bodyToCheck = eating ? snakeArr : snakeArr.slice(0, snakeArr.length - 1);
    if (bodyToCheck.some(s => s[0] === nx && s[1] === ny)) {
      die();
      return;
    }

    snakeArr.unshift([nx, ny]);
    if (eating) {
      scoreVal += 1;
      updateScore();
      placeFood();
    } else {
      snakeArr.pop();
    }
    draw();
  }

  function die() {
    aliveFlag = false;
    stopLoop();
    setStatus('Game Over — Score ' + scoreVal, true);
    draw();
  }

  function draw() {
    // background
    ctx.fillStyle = '#0b0e14';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // subtle grid
    ctx.strokeStyle = 'rgba(255,255,255,0.03)';
    ctx.lineWidth = 1;
    for (let i = 1; i < W; i++) {
      ctx.beginPath();
      ctx.moveTo(i * CELL, 0);
      ctx.lineTo(i * CELL, canvas.height);
      ctx.stroke();
    }
    for (let j = 1; j < H; j++) {
      ctx.beginPath();
      ctx.moveTo(0, j * CELL);
      ctx.lineTo(canvas.width, j * CELL);
      ctx.stroke();
    }

    // food
    if (foodPos) {
      const fx = foodPos[0] * CELL, fy = foodPos[1] * CELL;
      ctx.fillStyle = '#ff5a6e';
      ctx.beginPath();
      ctx.arc(fx + CELL / 2, fy + CELL / 2, CELL * 0.34, 0, Math.PI * 2);
      ctx.fill();
    }

    // snake
    for (let i = snakeArr.length - 1; i >= 0; i--) {
      const [x, y] = snakeArr[i];
      const px = x * CELL, py = y * CELL;
      if (i === 0) {
        ctx.fillStyle = aliveFlag ? '#7effc4' : '#c96b78';
      } else {
        const t = i / snakeArr.length;
        ctx.fillStyle = aliveFlag
          ? `rgb(${46 + t * 10}, ${224 - t * 90}, ${160 - t * 50})`
          : '#5a636f';
      }
      roundRect(px + 1, py + 1, CELL - 2, CELL - 2, 4);
      ctx.fill();
    }
  }

  function roundRect(x, y, w, h, r) {
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.arcTo(x + w, y, x + w, y + h, r);
    ctx.arcTo(x + w, y + h, x, y + h, r);
    ctx.arcTo(x, y + h, x, y, r);
    ctx.arcTo(x, y, x + w, y, r);
    ctx.closePath();
  }

  function startLoop() {
    if (loopId !== null) return;
    if (!aliveFlag) reset();
    setStatus('Playing');
    loopId = setInterval(tick, SPEED);
  }
  function stopLoop() {
    if (loopId !== null) { clearInterval(loopId); loopId = null; }
  }
  function pauseLoop() {
    if (loopId !== null) { stopLoop(); setStatus('Paused'); }
  }

  // keyboard
  const KEYMAP = {
    ArrowUp: 'up', ArrowDown: 'down', ArrowLeft: 'left', ArrowRight: 'right',
    w: 'up', s: 'down', a: 'left', d: 'right'
  };
  window.addEventListener('keydown', function (e) {
    const d = KEYMAP[e.key];
    if (d) {
      e.preventDefault();
      setDir(d);
      if (aliveFlag && loopId === null) startLoop();
    }
  });

  document.getElementById('start').addEventListener('click', startLoop);
  document.getElementById('pause').addEventListener('click', pauseLoop);
  document.getElementById('reset').addEventListener('click', function () {
    stopLoop();
    reset();
  });

  // expose API
  window.game = {
    w: W, h: H,
    reset: reset,
    tick: tick,
    setDir: setDir,
    setFood: setFood,
    snake: function () { return snakeArr.map(s => [s[0], s[1]]); },
    food: function () { return foodPos ? [foodPos[0], foodPos[1]] : null; },
    alive: function () { return aliveFlag; },
    score: function () { return scoreVal; }
  };

  reset();
})();
</script>
</body>
</html>
